mapper.select:
select id, dedupe_key as dedupeKey, payload_hash as payloadHash, source_id as sourceId, kind,
       region_id as regionId, board_id as boardId, season_id as seasonId, rules_release_id as rulesReleaseId,
       member_id as memberId, visit_id as visitId, service_id as serviceId, action_code as actionCode,
       goal_id as goalId, reason_code as reasonCode, amount, unit, currency, rating,
       detail_json as detailJson, occurred_at as occurredAt, create_time as createTime
from city_value_event
where region_id = #{regionId}
  and board_id = #{boardId}
  and season_id = #{seasonId}
  and rules_release_id = #{rulesReleaseId}
  and kind not in ('DEFINITION', 'COVERAGE')
  and occurred_at >= #{from}
  and occurred_at < #{to}

  and (occurred_at > #{cursorAt} or (occurred_at = #{cursorAt} and id > #{cursorId}))

order by occurred_at, id
limit #{limit}

select id, dedupe_key as dedupeKey, payload_hash as payloadHash, source_id as sourceId, kind,
       region_id as regionId, board_id as boardId, season_id as seasonId, rules_release_id as rulesReleaseId,
       member_id as memberId, visit_id as visitId, service_id as serviceId, action_code as actionCode,
       goal_id as goalId, reason_code as reasonCode, amount, unit, currency, rating,
       detail_json as detailJson, occurred_at as occurredAt, create_time as createTime
from city_value_event
where region_id = #{regionId}
  and board_id = #{boardId}
  and season_id = #{seasonId}
  and rules_release_id = #{rulesReleaseId}
  and kind in ('DEFINITION', 'COVERAGE')
order by id
limit #{limit}
